param(
  [switch]$NoCommit,
  [switch]$NoPush
)

$ErrorActionPreference = "Stop"
Set-StrictMode -Version Latest

function Say($text) {
  Write-Host "[Hinata OSS] $text" -ForegroundColor Cyan
}

function Write-B64($relativePath, $encoded) {
  $target = Join-Path (Get-Location) $relativePath
  $parent = Split-Path -Parent $target
  if ($parent -and -not (Test-Path $parent)) {
    New-Item -ItemType Directory -Force -Path $parent | Out-Null
  }
  [System.IO.File]::WriteAllBytes($target, [System.Convert]::FromBase64String($encoded))
}

Say "Checking repository..."
if (-not (Test-Path ".git")) {
  throw "Run this script from the root of your cloned hinata-bot repository."
}
if (-not (Test-Path "package.json")) {
  throw "package.json was not found. Make sure VS Code is opened at the hinata-bot root."
}

$remote = (git remote get-url origin 2>$null)
if ($LASTEXITCODE -ne 0 -or $remote -notmatch "ajaydudhaml01-arch/hinata-bot") {
  throw "This does not look like ajaydudhaml01-arch/hinata-bot. Origin: $remote"
}

$dirty = @(git status --porcelain)
if ($dirty.Count -gt 0) {
  Write-Host ""
  Write-Host "Your repo already has uncommitted changes:" -ForegroundColor Yellow
  $dirty | ForEach-Object { Write-Host "  $_" }
  Write-Host ""
  throw "Commit/stash those changes first, then run the upgrade again so nothing gets overwritten."
}

$stamp = Get-Date -Format "yyyyMMdd-HHmmss"
$backup = Join-Path ".oss-backup" $stamp
New-Item -ItemType Directory -Force -Path $backup | Out-Null

foreach ($p in @("README.md", "package.json", ".gitignore", "config.json", "data/levels.json")) {
  if (Test-Path $p) {
    $dest = Join-Path $backup $p
    $destParent = Split-Path -Parent $dest
    if ($destParent -and -not (Test-Path $destParent)) {
      New-Item -ItemType Directory -Force -Path $destParent | Out-Null
    }
    Copy-Item $p $dest -Force
  }
}
Say "Local backup created at $backup"

Say "Writing OSS files..."
Write-B64 "README.md" ""
Write-B64 "LICENSE" ""
Write-B64 "package.json" ""
Write-B64 ".gitignore" ""
Write-B64 "config.example.json" ""
Write-B64 "CONTRIBUTING.md" ""
Write-B64 "SECURITY.md" ""
Write-B64 "CODE_OF_CONDUCT.md" ""
Write-B64 "SUPPORT.md" ""
Write-B64 "ROADMAP.md" ""
Write-B64 "CHANGELOG.md" ""
Write-B64 "docs/ARCHITECTURE.md" ""
Write-B64 "tests/project.test.js" ""
Write-B64 ".github/workflows/ci.yml" ""
Write-B64 ".github/dependabot.yml" "dmVyc2lvbjogMgp1cGRhdGVzOgogIC0gcGFja2FnZS1lY29zeXN0ZW06ICJucG0iCiAgICBkaXJlY3Rvcnk6ICIvIgogICAgc2NoZWR1bGU6CiAgICAgIGludGVydmFsOiAid2Vla2x5IgogICAgb3Blbi1wdWxsLXJlcXVlc3RzLWxpbWl0OiA1Cg=="
Write-B64 ".github/CODEOWNERS" "KiBAYWpheWR1ZGhhbWwwMS1hcmNoCg=="
Write-B64 ".github/pull_request_template.md" ""
Write-B64 ".github/ISSUE_TEMPLATE/bug_report.yml" ""
Write-B64 ".github/ISSUE_TEMPLATE/feature_request.yml" ""
Write-B64 ".github/ISSUE_TEMPLATE/config.yml" "YmxhbmtfaXNzdWVzX2VuYWJsZWQ6IGZhbHNlCmNvbnRhY3RfbGlua3M6CiAgLSBuYW1lOiBVc2FnZSBhbmQgc2V0dXAgaGVscAogICAgdXJsOiBodHRwczovL2dpdGh1Yi5jb20vYWpheWR1ZGhhbWwwMS1hcmNoL2hpbmF0YS1ib3QvYmxvYi9tYWluL1NVUFBPUlQubWQKICAgIGFib3V0OiBSZWFkIHRoZSBzdXBwb3J0IGd1aWRlIGJlZm9yZSBvcGVuaW5nIGFuIGlzc3VlLgo="
Write-B64 ".editorconfig" "cm9vdCA9IHRydWUKClsqXQpjaGFyc2V0ID0gdXRmLTgKZW5kX29mX2xpbmUgPSBsZgppbnNlcnRfZmluYWxfbmV3bGluZSA9IHRydWUKaW5kZW50X3N0eWxlID0gc3BhY2UKaW5kZW50X3NpemUgPSAyCgpbKi5tZF0KdHJpbV90cmFpbGluZ193aGl0ZXNwYWNlID0gZmFsc2UK"
Write-B64 "data/.gitkeep" ""

# Keep the user's real local config/data, but stop tracking them publicly.
git ls-files --error-unmatch config.json *> $null
if ($LASTEXITCODE -eq 0) {
  git rm --cached -- config.json | Out-Host
}

git ls-files --error-unmatch data/levels.json *> $null
if ($LASTEXITCODE -eq 0) {
  git rm --cached -- data/levels.json | Out-Host
}

Say "Checking for obviously dangerous tracked secret filenames..."
$tracked = @(git ls-files)
$badTracked = $tracked | Where-Object { $_ -match '(^|/)(\.env|id_rsa|.*\.pem|.*\.p12|.*\.key)$' -and $_ -ne ".env.example" }
if ($badTracked.Count -gt 0) {
  Write-Host "WARNING: review these tracked files before pushing:" -ForegroundColor Red
  $badTracked | ForEach-Object { Write-Host "  $_" -ForegroundColor Red }
}

if (Get-Command npm -ErrorAction SilentlyContinue) {
  Say "Generating package-lock.json..."
  npm install --package-lock-only
  if ($LASTEXITCODE -ne 0) {
    throw "npm could not generate package-lock.json."
  }

  Say "Running syntax check..."
  npm run check
  if ($LASTEXITCODE -ne 0) {
    throw "Syntax check failed. No commit was made."
  }

  Say "Running tests..."
  npm test
  if ($LASTEXITCODE -ne 0) {
    throw "Tests failed. No commit was made."
  }
} else {
  Write-Host "npm was not found. Files were prepared, but package-lock/tests were skipped." -ForegroundColor Yellow
}

Say "Staging changes..."
git add -A

Write-Host ""
git status --short | Out-Host
Write-Host ""

if (-not $NoCommit) {
  $answer = Read-Host "Commit the OSS upgrade now? [Y/n]"
  if ([string]::IsNullOrWhiteSpace($answer) -or $answer -match '^[Yy]') {
    git commit -m "chore: prepare Hinata for open-source development"
    if ($LASTEXITCODE -ne 0) {
      throw "Git commit failed."
    }
    Say "Commit created."

    if (-not $NoPush) {
      $push = Read-Host "Push the commit to GitHub now? [Y/n]"
      if ([string]::IsNullOrWhiteSpace($push) -or $push -match '^[Yy]') {
        git push origin main
        if ($LASTEXITCODE -ne 0) {
          Write-Host "Push failed. Your commit is safe locally; push later from GitHub Desktop." -ForegroundColor Yellow
        } else {
          Say "Pushed to GitHub."
        }
      }
    }
  }
}

# Update repo metadata when GitHub CLI is already installed and authenticated.
if (Get-Command gh -ErrorAction SilentlyContinue) {
  gh auth status *> $null
  if ($LASTEXITCODE -eq 0) {
    Say "Updating repository description/topics with GitHub CLI..."
    gh repo edit ajaydudhaml01-arch/hinata-bot `
      --description "Modular open-source Discord.js bot for moderation, tickets, leveling, dynamic voice channels, self-roles, and community utilities." `
      --add-topic discord-bot `
      --add-topic discord-js `
      --add-topic moderation `
      --add-topic tickets `
      --add-topic leveling `
      --add-topic self-hosted *> $null
  }
}

Write-Host ""
Write-Host "============================================================" -ForegroundColor Green
Write-Host " Hinata OSS upgrade finished." -ForegroundColor Green
Write-Host "============================================================" -ForegroundColor Green
Write-Host ""
Write-Host "Next: check the GitHub Actions CI run. Once it is green, create the first release/tag." -ForegroundColor White
Write-Host "Backup: $backup" -ForegroundColor DarkGray
